<?php
if ( php_sapi_name() !== 'cli' ) { exit; } // solo terminal, nunca via web
/**
 * HOMVUK Autos PRO v3 (hvkp-autos3)
 *
 * Finaliza la fase anterior y agrega el post-pago, SIN archivos PHP en disco:
 *  1. Descripcion del Porsche corregida DIRECTO en la BD (sin hooks de
 *     plugins, que fue lo que fallo en el instalador anterior).
 *  2. Asegura la pagina de terminos como obligatoria en el checkout.
 *  3. Snippet v3: pagina de gracias PRO (proximos pasos + WhatsApp) y mails
 *     automaticos de vehiculos (bloque en el mail de pago, guia de cuidado
 *     al pagar, y mail de entrega 24 h antes del retiro).
 *  4. Branding de todos los correos WooCommerce (logo + color HOMVUK).
 *
 * Uso:  php hvkp-autos3.php            (instalar)
 *       php hvkp-autos3.php restore    (revertir esta fase)
 */

$HVKA_PORSCHE_B64 = '';
$HVKA_SNIPPET_B64 = '';
$HVKA_SNIPPET_MD5 = 'e8d318d4786b8e5eb1263d8344855a75';
$HVKA_NAME        = 'HOMVUK Autos PRO';

require __DIR__ . '/wp-load.php';
global $wpdb;

$mode  = isset( $argv[1] ) ? $argv[1] : 'install';
$ok    = array();
$warn  = array();
$table = $wpdb->prefix . 'snippets';

$purge_caches = function () {
    if ( class_exists( '\Elementor\Plugin' ) ) {
        try { \Elementor\Plugin::instance()->files_manager->clear_cache(); } catch ( \Throwable $e ) {}
    }
    if ( function_exists( 'wp_cache_flush' ) ) { wp_cache_flush(); }
    do_action( 'litespeed_purge_all' );
    if ( function_exists( 'rocket_clean_domain' ) ) { rocket_clean_domain(); }
    if ( function_exists( 'w3tc_flush_all' ) ) { w3tc_flush_all(); }
    if ( function_exists( 'wp_cache_clear_cache' ) ) { wp_cache_clear_cache(); }
};

if ( 'restore' === $mode ) {
    $b = get_option( 'hvkp_autos3_backup' );
    if ( ! is_array( $b ) ) {
        echo "[AVISO] No hay respaldo de esta fase; nada que restaurar.\n";
        exit( 0 );
    }
    if ( isset( $b['snippet_code'] ) && '' !== $b['snippet_code'] ) {
        $wpdb->update( $table, array( 'code' => $b['snippet_code'] ), array( 'name' => $HVKA_NAME ) );
        echo "[OK]    Snippet restaurado a la version anterior\n";
    }
    if ( isset( $b['porsche_id'], $b['porsche_content'] ) && $b['porsche_id'] ) {
        $wpdb->update( $wpdb->posts, array( 'post_content' => $b['porsche_content'] ), array( 'ID' => (int) $b['porsche_id'] ) );
        clean_post_cache( (int) $b['porsche_id'] );
        echo "[OK]    Descripcion anterior del Porsche restaurada\n";
    }
    foreach ( array( 'woocommerce_email_base_color' => 'email_color', 'woocommerce_email_header_image' => 'email_logo', 'woocommerce_email_footer_text' => 'email_footer' ) as $opt => $k ) {
        if ( isset( $b[ $k ] ) ) { update_option( $opt, $b[ $k ] ); }
    }
    echo "[OK]    Opciones de correo restauradas\n";
    $purge_caches();
    echo "Restauracion completa.\n";
    exit( 0 );
}

$backup = array();

// 1) Descripcion del Porsche directo en wp_posts (sin disparar hooks de plugins)
$pid = $wpdb->get_var(
    "SELECT ID FROM {$wpdb->posts} WHERE post_name = 'porsche-cayenne-2018' AND post_type = 'product' AND post_status = 'publish' LIMIT 1"
);
if ( $pid ) {
    $old = $wpdb->get_var( $wpdb->prepare( "SELECT post_content FROM {$wpdb->posts} WHERE ID = %d", $pid ) );
    if ( false === strpos( (string) $old, 'Porsche Cayenne 2018' ) ) {
        $backup['porsche_id']      = (int) $pid;
        $backup['porsche_content'] = (string) $old;
        $wpdb->update( $wpdb->posts, array( 'post_content' => base64_decode( $HVKA_PORSCHE_B64 ) ), array( 'ID' => (int) $pid ) );
        clean_post_cache( (int) $pid );
        $ok[] = "Descripcion del Porsche Cayenne 2018 corregida (post $pid, ya no muestra la ficha del MG3)";
    } else {
        $ok[] = 'La descripcion del Porsche ya estaba corregida';
    }
} else {
    $warn[] = 'No se encontro el producto porsche-cayenne-2018';
}

// 2) Asegurar la pagina de terminos en el checkout
$terms = get_page_by_path( 'terminos-y-condiciones-de-arriendo', OBJECT, 'page' );
if ( $terms && 'publish' === $terms->post_status ) {
    if ( (int) get_option( 'woocommerce_terms_page_id', 0 ) !== (int) $terms->ID ) {
        update_option( 'woocommerce_terms_page_id', (int) $terms->ID );
    }
    $ok[] = 'Casilla obligatoria "Acepto los terminos y condiciones" activa en el checkout (pagina ' . $terms->ID . ')';
} else {
    $warn[] = 'La pagina de terminos no esta publicada';
}

// 3) Snippet v3 (md5 verificado): post-pago + mails automaticos
$code = base64_decode( $HVKA_SNIPPET_B64 );
if ( md5( $code ) !== $HVKA_SNIPPET_MD5 ) {
    echo "[ERROR] El snippet embebido no paso la verificacion md5. Nada mas fue modificado.\n";
    exit( 1 );
}
$prev = $wpdb->get_row( $wpdb->prepare( "SELECT id, code FROM $table WHERE name = %s", $HVKA_NAME ) );
if ( ! $prev ) {
    echo "[ERROR] No existe el snippet 'HOMVUK Autos PRO' (corre primero hvkp-autos.php).\n";
    exit( 1 );
}
$backup['snippet_code'] = $prev->code;
$wpdb->update(
    $table,
    array( 'code' => $code, 'scope' => 'global', 'active' => 1, 'modified' => current_time( 'mysql' ) ),
    array( 'id' => (int) $prev->id )
);
$ok[] = 'Snippet actualizado a v3: pagina de gracias PRO + mails automaticos (id ' . $prev->id . ')';

// 4) Branding de correos WooCommerce (todos los mails del sitio)
$backup['email_color']  = get_option( 'woocommerce_email_base_color', '' );
$backup['email_logo']   = get_option( 'woocommerce_email_header_image', '' );
$backup['email_footer'] = get_option( 'woocommerce_email_footer_text', '' );
update_option( 'woocommerce_email_base_color', '#d63384' );
update_option( 'woocommerce_email_header_image', home_url( '/wp-content/uploads/2023/06/logo50-light.png' ) );
update_option( 'woocommerce_email_footer_text', 'HOMVUK — Arriendo premium de propiedades y vehículos · WhatsApp +56 9 4021 1459 · {site_url}' );
$ok[] = 'Correos WooCommerce con marca HOMVUK (logo + color #d63384 + pie con WhatsApp)';

update_option( 'hvkp_autos3_backup', $backup, false );

// 5) Purga y verificacion en vivo
$purge_caches();
$resp = wp_remote_get( home_url( '/experiencia/porsche-cayenne-2018/?hvka3=' . time() ), array( 'timeout' => 30, 'sslverify' => false ) );
if ( ! is_wp_error( $resp ) ) {
    $body = (string) wp_remote_retrieve_body( $resp );
    if ( false === strpos( $body, 'El MG3' ) && false !== strpos( $body, 'SUV premium' ) ) {
        $ok[] = 'Verificado: descripcion nueva del Porsche visible en la web';
    } else {
        $warn[] = 'La descripcion nueva aun no se ve (puede ser cache; revisar en unos minutos)';
    }
    if ( false !== strpos( $body, 'hvka_doc_id' ) ) {
        $ok[] = 'Verificado: snippet activo (campos de documentos presentes)';
    } else {
        $warn[] = 'El snippet no aparece en la pagina del auto; revisar';
    }
} else {
    $warn[] = 'No se pudo verificar en vivo: ' . $resp->get_error_message();
}

echo "== HOMVUK Autos PRO v3 (post-pago + mails, sin archivos PHP persistentes) ==\n";
foreach ( $ok as $m )   { echo "[OK]    $m\n"; }
foreach ( $warn as $m ) { echo "[AVISO] $m\n"; }
echo "Listo. Este instalador puede borrarse: rm -f hvkp-autos3.php\n";
echo "Para revertir esta fase: php hvkp-autos3.php restore\n";
